/// <summary>
/// When the checkbox for flipping the checkboxes in a certain group is changed.
/// </summary>
public void selectAllButton(FormCheckBoxControl _formButtonControl)
{
    str modelName = _formButtonControl.parentControl().name();
    _formButtonControl.value(!_formButtonControl.value());

    if(!checkmarkFields.exists(modelName)) 
    {
        return;
    }

    Map checkMarksForModel = checkmarkFields.lookup(modelName);
    MapEnumerator mEnum = checkMarksForModel.getEnumerator();
    int setInt = -1;
    while(mEnum.moveNext())
    {
        DialogField dField = mEnum.currentValue();
        if(setInt == -1)
        {
            setInt = !dField.value();
        }
        dField.value(setInt);
    }
}

/// <summary>
/// Dialog displayed for the user with tables that can be migrated to the new model.
/// </summary>
/// <returns></returns>
public Object dialog()
{
    Dialog                      dialog = super();
    Map                         models = MobDataMigratorPlatformModelSetup::getTables();
    MapEnumerator               modelEnum = models.getEnumerator();
    MapEnumerator               tableEnum;     
    common                      common;
    checkmarkFields = new Map(Types::String, Types::Class);
    Map checkmarkFieldsForModel;

    str classicModelName = 'TF Mobile';
    str platformModelName = "@TFM:MEL18";

    // Set a title for dialog
    dialog.caption("@TFM:MigratedatatonewTFplatform");
    dialog.addText("@TFM:Unselectedfieldscontainsdatainth");

    fields = new Map (Types::String, Types::Class);
    Map platformTables = models.lookup(platformModelName);

    while (modelEnum.moveNext())
    {
        if(modelEnum.currentKey() == platformModelName)
        {
            continue; //only the other models are interesting
        }

        checkmarkFieldsForModel = new Map(Types::String, Types::Class);

        Map tables = modelEnum.currentValue();
        if(tables.elements())
        {
            dlg = dialog.addGroup(modelEnum.currentKey(), null, modelEnum.currentKey());
            dlg.columns(1);
            selectcheckmarkField = dialog.addField(extendedTypeStr(NoYesId), "@TFM:Selectdeselectall", "@TFM:Flipthecheckboxesforthegroup");

            selectcheckmarkField.registerOverrideMethod(
            methodStr(FormCheckBoxControl, clicked),
            methodStr(MobDataMigratorPlatformModelSetup, selectAllButton),
            this);
        }

        dlg = dialog.addGroup();
        dlg.columns(2);
        dlg.hideIfEmpty(false);

        tableEnum = modelEnum.currentValue().GetEnumerator();
        while (tableEnum.moveNext())
        {
            //check if the table is in Mob - tables
            if(!platformTables.exists(this.convertToTFMModel(tableEnum.currentKey())) || !this.hasData(tableEnum.currentKey())) // check if the table in the model exists in the
            {
                continue;
            }
            checkmarkField = dialog.addField(extendedTypeStr(NoYesId), tableEnum.currentValue() ? tableEnum.currentValue() : tableEnum.currentKey(), tableEnum.currentKey());
            checkmarkField.value(!this.hasData(this.convertToTFMModel(tableEnum.currentKey())));
            checkmarkFieldsForModel.add(checkmarkField.name(), checkmarkField);
            fields.insert(tableEnum.currentKey(),checkmarkField);
        }
        checkmarkFields.add(modelEnum.currentKey(), checkmarkFieldsForModel);
    }

    dlg = dialog.addGroup("@TFM:MigrationSetup");
    dlg.columns(1);
    dlg.heightMode(FormHeight::SizeToAvailable);
    outputCheckmarkField = dialog.addField(extendedTypeStr(NoYesId), "@TFM:Onlyoutputfile", "@TFM:Outputtheasfileonlyinsteadofupda");

    return dialog;
}

public void reloadDialog(FormCheckBoxControl _ctrl)
{
    this.dialog();
}

/// <summary>
/// Converts the input to the correct migration for Mob -> TFM. It uses the MigrationMap to find the correct migration.
/// If nothing is found in the a simple rename is used.
/// </summary>
/// <param name = "_input"></param>
/// <returns></returns>
private str convertToTFMModel(str _input)
{
    Map migrationMap = this.getMigrationMap();
    if(migrationMap.exists(_input))
    {
        return migrationMap.lookup(_input);
    }
    return strReplace(_input, 'Mob', 'TFM');
}

/// <summary>
/// Checks if a certain table contains data.
/// </summary>
/// <param name = "_tableName">The name of the table</param>
/// <returns>True, if the table contains data otherwise false.</returns>
private boolean hasData(str _tableName)
{
    DictTable dictTable = new DictTable(tableName2Id(_tableName));
    Common common;
    boolean hasData = false;
    if (dictTable)
    {
        common = dictTable.makeRecord();
        select firstOnly common;
        if (common.RecId)
        {
            hasData = true;
        }
    }
    return hasData;
}

