/// <summary>
/// The run method that will be run when the accept/ok button is clicked.
/// </summary>
public void run()
{
    MapEnumerator mEnum = fields.getEnumerator();
    str             output;

    while ( mEnum.moveNext())
    {
        checkmarkField = mEnum.currentValue();
        if (!checkmarkField.value())
        {
            continue;
        }
        str tableOutput = this.getTable(mEnum.currentKey());

        tableOutput = this.convertTable(mEnum.currentKey(), tableOutput);

        output += tableOutput;
    }

    if(outputCheckmarkField.value())
    {
        this.sendFileToUser(output);
    } 
    else
    {
        TFMImportSetup::importFromText(output);
        this.postRunFixes();
        TFMProvider::invalidateProviders(); // invalidate the providers so the data from the delta layer will be used.
        Info("@TFM:Dataimported");
    }
}

protected void postRunFixes()
{
    //Lists fixes
    this.listsCheck();

    //online Validation fix
    this.fixOnlineValidation();
    //Menu group Folder fix
    this.fixMenuGroupFolder();
}

protected void fixMenuGroupFolder()
{
    MobMenuGroups fromGroup;
    TFMMenuGroups toGroup;

    if (!fields.exists(tableStr(MobMenuGroups)) && !fields.exists(tableStr(TFMMenuGroups)))
    {
        return;
    }
    ttsbegin;
    while select fromGroup where fromGroup.ShowFolder
    {
        toGroup = TFMMenuGroups::Find(fromGroup.MenuGroupId,true);
        toGroup.GroupingTypeIcon = 'Folder';
        toGroup.update();
    }
    ttscommit;
}

protected void fixOnlineValidation()
{
    MobWorkflowStepsOnlineValidation fromValidate;
    TFMWorkflowStepsOnlineValidation toValidate;

    if (!fields.exists(tableStr(MobWorkflowStepsOnlineValidation)) && !fields.exists(tableStr(TFMWorkflowStepsOnlineValidation)))
    {
        return;
    }

    delete_from toValidate where !toValidate.ValidationType;

    while select fromValidate
    {
        toValidate.WorkflowName     = fromValidate.WorkflowName;
        toValidate.DocumentTypeId   = fromValidate.DocumentTypeId;
        toValidate.PageID           = fromValidate.PageID;
        toValidate.ValidationType   = enum2Symbol(enumNum(MobWorkflowValidationTypes), fromValidate.ValidationTypes);
        toValidate.insert();
    }

}

protected void listsCheck()
{
    TFMLists            listTbl;

    TFMListNode         listNode, listNodeParent;
    TFMListAttribute    listAttr;
    MobListNode         oldListNode;
    MobListAttribute    oldListAttr;
    Set                 reimportList = new Set(Types::String);
    SetEnumerator       sEnum;
    Map                 recId2recId = new Map(Types::Int64, Types::Int64);
    Map                 migrationMap = this.getMigrationMap();

    while select listTbl
    {
        select firstonly listNodeParent where listNodeParent.ListId == listTbl.ListId && !listNodeParent.parentNode;
        select firstonly listNode where listNode.parentNode == listNodeParent.recid;

        if (!listNode)
        {
            reimportList.add(listTbl.ListId);
        }
    }

    sEnum = reimportList.getEnumerator();
    ttsbegin;
    while(sEnum.moveNext())
    {
        delete_from listNodeParent where listNodeParent.ListId == sEnum.current();

        while select oldListNode where oldListNode.ListId == sEnum.current()
        {
            buf2Buf(oldListNode, listNode);
            listNode.NodeName = migrationMap.exists(listNode.NodeName) ? migrationMap.lookup(listNode.NodeName) : listNode.NodeName;
            listNode.insert();
            recId2recId.insert(oldListNode.RecId,listNode.RecId);
        }
        while Select forupdate listNode where listNode.ListId == sEnum.current()
        {
            listNode.ParentNode = recId2recId.exists(listNode.ParentNode) ? recId2recId.lookup(listNode.ParentNode) : listNode.ParentNode;
            listNode.update();
        }

        while select forupdate listAttr
        {
            listAttr.ParentNode = recId2recId.exists(listAttr.ParentNode) ? recId2recId.lookup(listAttr.ParentNode) : listAttr.ParentNode;
            listAttr.update();
        }
    }

    ttscommit;
}

/// <summary>
/// Converts the a table output to TFM tables and content. 
/// </summary>
/// <param name = "_tableName"></param>
/// <param name = "_tableOutput"></param>
/// <returns></returns>
private str convertTable(str _tableName, str _tableOutput)
{
    str tableOutput = _tableOutput;
    Map migrationMap = this.getMigrationMap();
    MapEnumerator mEnum = migrationMap.getEnumerator();

    while(mEnum.moveNext())
    {
        tableOutput = this.FindMobWordsAndReplace(tableOutput, migrationMap);
    }

    return tableOutput;
}

/// <summary>
/// Finds Mob words and replaces it with the corresponding TFM class/table if any.
/// </summary>
/// <param name = "_input"></param>
/// <param name = "_migrationMap"></param>
/// <returns></returns>
public str FindMobWordsAndReplace(str _input, Map _migrationMap)
{
    str output = _input;
    System.Text.RegularExpressions.MatchCollection matches;
    System.Text.RegularExpressions.Match match;
    System.Text.RegularExpressions.Regex regex;
    str pattern = @"\bMob\w*";

    regex = new System.Text.RegularExpressions.Regex(pattern);
    matches = regex.Matches(_input);

    for (int i = 0; i < matches.get_Count(); i++)
    {
        match = matches.get_Item(i);

        //if the TFM name exists then replace Mob with TFM
        str classNameStr = match.get_Value();
        str tfmClassNameStr = this.convertToTFMModel(classNameStr);
        if(_migrationMap.exists(classNameStr) 
            || tableName2Id(tfmClassNameStr)
            || className2Id(tfmClassNameStr))
        {
            output = strReplace(output, classNameStr, tfmClassNameStr);
        }
    }
    return output;
}

/// <summary>
/// Sends the file to the user to download.
/// </summary>
/// <param name = "_output">The content of the file to output.</param>
private void sendFileToUser(str _output)
{
    str fileName = 'TFMExport';
    str contentType = 'application/text';
    str fileExtension = '.tfe';
    #if.isAX6
    System.IO.StreamWriter sw;
    str filePath = WinAPI::getSaveFileName(0,['Tasklet Factory Export format','*'+fileExtension],'',"@SYS56237",fileExtension,fileName);
    InteropPermission perm = new InteropPermission(InteropKind::ClrInterop);
    perm.assert();

    sw = new System.IO.StreamWriter(filePath);
    sw.Write(_output);
    sw.Flush();
    sw.Close();
    sw.Dispose();

    CodeAccessPermission::revertAssert();


    #endif
    #ifnot.IsAX6 //365
    System.IO.MemoryStream stream = new System.IO.MemoryStream();
    System.IO.StreamWriter writer = new System.IO.StreamWriter(stream,System.Text.Encoding::GetEncoding(1252));
    writer.Write(_output);
    writer.Flush();

    stream.Position = 0;
    FileUploadTemporaryStorageStrategy fileUploadStrategy = new FileUploadTemporaryStorageStrategy();
    FileUploadTemporaryStorageResult fileUploadResult = fileUploadStrategy.uploadFile(stream, fileName + fileExtension, contentType , fileExtension);
    Browser br = new Browser();
    br.navigate(fileUploadResult.getDownloadUrl(),false, false);
    #endif
}

/// <summary>
/// Gets output of the table.
/// </summary>
/// <param name = "_tableName">The name of the table.</param>
/// <returns>String output for the table in the TFE format.</returns>
private str getTable(TableName _tableName)
{
    str             output;
    str             tmpStr;
    int             endPos;
    str             addedFields;
    Map             refs;
    MapEnumerator   refsEnum;
    Common table = new SysDictTable(tableName2Id(_tableName)).makeRecord();
    while select table
    {
        addedFields = '';
        tmpStr = table.xml();
        endPos = strScan(tmpStr, '</Table:Record>',1, strLen(tmpStr));
        refs =  this.addClassReferenceKey(table);
        refs.insert('RecId',int642Str(table.RecId));
        refsEnum = refs.getEnumerator();
        while (refsEnum.moveNext())
        {
            addedFields += '<Table:Field name="'+refsEnum.currentKey()+'">'+refsEnum.currentValue()+'</Table:Field>' + "@TFM:lineBreak";
        }
        tmpStr = subStr(tmpStr,1,endPos-1) + addedFields + subStr(tmpStr,endPos, strLen(tmpStr));
        output += tmpStr;
    }
    return output;
}

private Map addClassReferenceKey(Common _table)
{
    DictTable       dt          = new DictTable(_table.tableId);
    Map             classRefs   = new Map(Types::String, Types::String);
    dictField       df;
    int             fieldCount  = dt.fieldCnt();
    int             fieldNo     = 0;

    for (fieldNo = 0; fieldNo <= fieldCount; fieldNo++)
    {
        df = new DictField(_table.tableId,dt.fieldCnt2Id(fieldNo));
        if (df.typeId() && (new DictType(df.typeId()).extend() == extendedTypeNum(ClassId) || df.typeId() == extendedTypeNum(ClassId)))
        {
            classRefs.insert(df.name() + 'AOTName', classId2Name(_table.(dt.fieldCnt2Id(fieldNo))));
        }
    }

    return classRefs;
}

